$race=static function(array $forms,array $users):array{
    $children=[];
    foreach($forms as $i=>$form){$file=App::storage('tmp/guest-race-'.bin2hex(random_bytes(5)).'.json');file_put_contents($file,json_encode(['user'=>$users[$i],'form'=>$form]));
        $command=[PHP_BINARY];if($ini=php_ini_loaded_file())array_push($command,'-c',$ini);array_push($command,__FILE__,'--worker',$file);
        $process=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new RuntimeException('Worker failed to start.');fclose($pipes[0]);$children[]=[$process,$pipes];}
    $results=[];foreach($children as [$process,$pipes]){$out=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($process)!==0)throw new RuntimeException($error.$out);$results[]=json_decode($out,true,512,JSON_THROW_ON_ERROR);}return $results;
};
